func TestT7Split(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	h := g.Source
	f0 := refCurve(t, m, "f0_pred")

	for i := 0; i < 3; i++ {
		n := len(f0) * h.UpsampleScale
		dim := h.Harmonics + 1

		t0 := time.Now()
		f0Up := make([]float32, n)
		uv := make([]float32, n)
		for j := range f0Up {
			f0Up[j] = f0[j/h.UpsampleScale]
			if f0Up[j] > h.VoicedThreshold {
				uv[j] = 1
			}
		}
		t1 := time.Now()
		rad := make([]float64, n*dim)
		for j, v := range f0Up {
			for d := 0; d < dim; d++ {
				x := float64(v) * float64(d+1) / float64(h.SampleRate)
				rad[j*dim+d] = x - math.Floor(x)
			}
		}
		t2 := time.Now()
		low := interpolateLinear(rad, dim, len(f0))
		phase := make([]float64, len(f0)*dim)
		for d := 0; d < dim; d++ {
			var acc float64
			for tt := 0; tt < len(f0); tt++ {
				acc += low[tt*dim+d]
				phase[tt*dim+d] = acc * float64(h.UpsampleScale)
			}
		}
		t3 := time.Now()
		full := interpolateLinear(phase, dim, n)
		t4 := time.Now()
		sines := NewMat(n, dim)
		for j, p := range full {
			sines.Data[j] = float32(math.Sin(2*math.Pi*(p-math.Floor(p)))) * h.SineAmp * uv[j/dim]
		}
		t5 := time.Now()
		source := make([]float32, n)
		row := make([]float32, 1)
		for tt := 0; tt < n; tt++ {
			h.Mix.ApplyRow(row, sines.Row(tt))
			source[tt] = tanh(row[0])
		}
		t6 := time.Now()

		// The STFT half.
		mag, ph := g.STFT.MagnitudePhase(source)
		t7 := time.Now()
		_ = mag
		_ = ph
		har := g.Harmonic(source)
		t8 := time.Now()
		_ = har

		t.Logf("run %d: upsample=%v rad=%v cumsum(down+int)=%v interpUp=%v sin=%v mix=%v || MagPhase=%v Harmonic(all)=%v",
			i, t1.Sub(t0), t2.Sub(t1), t3.Sub(t2), t4.Sub(t3), t5.Sub(t4), t6.Sub(t5), t7.Sub(t6), t8.Sub(t7))
	}
}

func TestT7DFTOnly(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	source, _, _, _ := g.Source.Apply(f0)
	bins := g.STFT.Bins()
	frames := g.STFT.Frames(len(source))
	t.Logf("frames=%d bins=%d nfft=%d hop=%d", frames, bins, g.STFT.NFFT, g.STFT.Hop)
	for i := 0; i < 3; i++ {
		t0 := time.Now()
		mag, ph := g.STFT.MagnitudePhase(source)
		t1 := time.Now()
		// the cost of the transcendentals alone, over the same data
		var s float64
		for j := range mag {
			s += math.Hypot(mag[j], ph[j]) + math.Atan2(ph[j], mag[j])
		}
		t2 := time.Now()
		t.Logf("run %d: MagnitudePhase=%v  (%d hypot+atan2 pairs = %v)  sink=%g",
			i, t1.Sub(t0), len(mag), t2.Sub(t1), s)
	}
}
