// The claim: interpolateLinear(rad, dim, len(f0)) is the identity on the
// per-frame value. The 300:1 decimation reads coordinate 300t+149.5, so i0 =
// 300t+149 and i1 = 300t+150 with w = 0.5 -- and *both* lie in f0 frame t,
// because nearest upsampling made all 300 of frame t's samples equal. Half of
// x plus half of x is x exactly.
func TestT7DecimationIsIdentity(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	h := model.Vocoder.Generator.Source
	f0 := refCurve(t, m, "f0_pred")

	n := len(f0) * h.UpsampleScale
	dim := h.Harmonics + 1
	f0Up := make([]float32, n)
	for j := range f0Up {
		f0Up[j] = f0[j/h.UpsampleScale]
	}
	rad := make([]float64, n*dim)
	for j, v := range f0Up {
		for d := 0; d < dim; d++ {
			x := float64(v) * float64(d+1) / float64(h.SampleRate)
			rad[j*dim+d] = x - math.Floor(x)
		}
	}
	low := interpolateLinear(rad, dim, len(f0))

	var worst float64
	for tt := 0; tt < len(f0); tt++ {
		for d := 0; d < dim; d++ {
			x := float64(f0[tt]) * float64(d+1) / float64(h.SampleRate)
			want := x - math.Floor(x)
			if g := math.Abs(low[tt*dim+d] - want); g > worst {
				worst = g
			}
		}
	}
	t.Logf("worst gap between the decimation and frac(f0*(d+1)/SR): %g", worst)
	if worst != 0 {
		t.Errorf("not identical: %g", worst)
	}
}
