package kokoro

import (
	"math"
	"testing"
	"time"
)

// newTestSource builds the excitation for the dump's curve.
func newTestSource(t *testing.T) (*GPUSource, *Generator, []float32, func()) {
	t.Helper()
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	dev, done := newTestDevice(t)
	s, err := NewGPUSource(dev, g, len(f0)+64)
	if err != nil {
		done()
		t.Fatal(err)
	}
	return s, g, f0, func() { s.Destroy(); done() }
}

// TestGPUSourceAgainstHost is T7's measurement: the device excitation against
// the float64 host reference, which is itself more accurate than the dump.
//
// The waveform is checked in absolute terms rather than relative ones. It is
// tanh of a mixer output, so it lives in [-1, 1] and has genuine zero
// crossings; a relative bound at a zero crossing measures nothing but where
// the crossing landed.
func TestGPUSourceAgainstHost(t *testing.T) {
	s, g, f0, done := newTestSource(t)
	defer done()

	wantSource, _, _, _ := g.Source.Apply(f0)
	wantHar := g.Harmonic(wantSource)

	gotSource, gotHar, err := s.Apply(f0)
	if err != nil {
		t.Fatal(err)
	}
	if len(gotSource) != len(wantSource) {
		t.Fatalf("%d samples, the host produced %d", len(gotSource), len(wantSource))
	}
	if gotHar.Rows != wantHar.Rows || gotHar.Cols != wantHar.Cols {
		t.Fatalf("harmonic %v, the host produced %v", gotHar, wantHar)
	}

	var worst float64
	var at int
	var sum float64
	for i := range gotSource {
		d := math.Abs(float64(gotSource[i]) - float64(wantSource[i]))
		sum += d * d
		if d > worst {
			worst, at = d, i
		}
	}
	rms := math.Sqrt(sum / float64(len(gotSource)))
	t.Logf("source: worst %.3g at %d, rms %.3g over %d samples", worst, at, rms, len(gotSource))
	// The excitation is a sine bank evaluated at a phase carried in wrapped
	// cycles, so the device's error is one float32 ulp of a number below 301
	// -- 3e-5 cycles, 2e-4 radians -- times the mixer. 1e-3 is two decades
	// above the observed rms and three below the signal.
	if worst > 1e-3 {
		t.Errorf("the device waveform differs from the host's by %.3g at %d", worst, at)
	}

	// The magnitude is what the network is conditioned on; the phase is
	// numerically undefined wherever the magnitude is zero (Generator.
	// Harmonic), so it is checked only where there is a magnitude to define
	// it.
	bins := gotHar.Cols / 2
	var magWorst, phWorst float64
	var magAt, phAt, phN int
	for r := 0; r < gotHar.Rows; r++ {
		for b := 0; b < bins; b++ {
			i := r*gotHar.Cols + b
			if d := math.Abs(float64(gotHar.Data[i]) - float64(wantHar.Data[i])); d > magWorst {
				magWorst, magAt = d, i
			}
			if float64(wantHar.Data[i]) < 1e-4 {
				continue
			}
			phN++
			j := i + bins
			d := math.Abs(float64(gotHar.Data[j]) - float64(wantHar.Data[j]))
			if d > math.Pi {
				d = 2*math.Pi - d // the branch cut at +-pi is not an error
			}
			if d > phWorst {
				phWorst, phAt = d, j
			}
		}
	}
	t.Logf("harmonic: magnitude worst %.3g at %d; phase worst %.3g at %d over %d bins with a magnitude",
		magWorst, magAt, phWorst, phAt, phN)
	if magWorst > 1e-4 {
		t.Errorf("the device magnitude differs by %.3g at %d", magWorst, magAt)
	}
	if phWorst > 1e-3 {
		t.Errorf("the device phase differs by %.3g rad at %d", phWorst, phAt)
	}
}

// TestGPUSourceWaveform is the measurement that matters: what the difference
// above does to the *waveform*, run through the rest of the vocoder.
func TestGPUSourceWaveform(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	asr := refMat(t, m, "asr")
	decStyle, _, err := model.Style("af_heart", 48)
	if err != nil {
		t.Fatal(err)
	}
	energy := refCurve(t, m, "n_pred")

	dev, done := newTestDevice(t)
	defer done()
	s, err := NewGPUSource(dev, g, len(f0)+64)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Destroy()

	wantWav, _, err := model.Vocoder.Apply(asr, f0, energy, decStyle)
	if err != nil {
		t.Fatal(err)
	}
	_, har, err := s.Apply(f0)
	if err != nil {
		t.Fatal(err)
	}
	dec, err := model.Vocoder.Decoder.Apply(asr, f0, energy, decStyle)
	if err != nil {
		t.Fatal(err)
	}
	gotWav, _, err := g.ApplyWithHarmonic(dec, decStyle, har)
	if err != nil {
		t.Fatal(err)
	}
	if len(gotWav) != len(wantWav) {
		t.Fatalf("%d samples against %d", len(gotWav), len(wantWav))
	}
	d := compare(t, gotWav, wantWav)
	t.Logf("waveform: relative %.3g, max abs %.3g at %d, rms %.3g, %.1f dB",
		d.Rel(), d.MaxAbs, d.At, d.RMS, 20*math.Log10(1/d.Rel()))
	if d.Rel() > 1e-3 {
		t.Errorf("the device excitation moves the waveform by %.3g relative", d.Rel())
	}
}

// TestGPUSourceTime is T7's headline: the stage's wall clock against the
// 14 ms the host takes for the same two steps.
func TestGPUSourceTime(t *testing.T) {
	s, g, f0, done := newTestSource(t)
	defer done()

	var host time.Duration
	for i := 0; i < 3; i++ {
		t0 := time.Now()
		src, _, _, _ := g.Source.Apply(f0)
		g.Harmonic(src)
		if d := time.Since(t0); host == 0 || d < host {
			host = d
		}
	}

	var wall, upload, run, down time.Duration
	for i := 0; i < 5; i++ {
		t0 := time.Now()
		if err := s.Upload(f0); err != nil {
			t.Fatal(err)
		}
		t1 := time.Now()
		if err := s.Run(); err != nil {
			t.Fatal(err)
		}
		t2 := time.Now()
		s.Source()
		s.Harmonic()
		t3 := time.Now()
		if d := t3.Sub(t0); wall == 0 || d < wall {
			wall, upload, run, down = d, t1.Sub(t0), t2.Sub(t1), t3.Sub(t2)
		}
	}
	stages, err := s.Profile()
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("host %v -> device %v (upload %v, submit %v, download %v), %.1fx",
		host, wall, upload, run, down, float64(host)/float64(wall))
	for _, st := range stages {
		t.Logf("  %-8s %6.3f ms", st.Kind, st.Time*1e3)
	}
}
