	// disagreement is there.
	var zero, big int
	var maxMag float64
	for i := 0; i < hostHar.Rows; i++ {
		for b := 0; b < bins; b++ {
			mg := float64(hostHar.Data[i*hostHar.Cols+b])
			if mg > maxMag {
				maxMag = mg
			}
			if mg < 1e-6 {
				zero++
				d := math.Abs(float64(devHar.Data[i*hostHar.Cols+bins+b]) -
					float64(hostHar.Data[i*hostHar.Cols+bins+b]))
				if d > 0.1 {
					big++
				}
			}
		}
	}
	t.Logf("%d of %d bins have magnitude < 1e-6 (max magnitude %.3g); %d of those disagree in phase by > 0.1 rad",
		zero, hostHar.Rows*bins, maxMag, big)

	mix := func(name string, useDevMag, useDevPhaseDefined, useDevPhaseUndefined bool) {
		h := &Mat{Rows: hostHar.Rows, Cols: hostHar.Cols,
			Data: append([]float32{}, hostHar.Data...)}
		for i := 0; i < h.Rows; i++ {
