	defer s.Destroy()

	want := refCurve(t, m, "audio")
	hostWav, tr, err := model.Vocoder.Apply(asr, f0, energy, decStyle)
	if err != nil {
		t.Fatal(err)
	}
	x := tr.Decode[len(tr.Decode)-1]

	_, har, err := s.Apply(f0)
	if err != nil {
		t.Fatal(err)
	}
	devWav, _, err := g.ApplyWithHarmonic(x, decStyle, har)
	if err != nil {
		t.Fatal(err)
	}
	h := compare(t, hostWav, want)
	d := compare(t, devWav, want)
	t.Logf("against the reference: host %.4g (%.1f dB), device %.4g (%.1f dB)",
		h.Rel(), -20*math.Log10(h.Rel()), d.Rel(), -20*math.Log10(d.Rel()))

	// And the excitation waveform itself, which is defined everywhere.
	refSrc := refCurve(t, m, "har_source")
	hostSrc, _, _, _ := g.Source.Apply(f0)
	devSrc, _, err := s.Apply(f0)
	if err != nil {
		t.Fatal(err)
	}
	hs := compare(t, hostSrc, refSrc)
	ds := compare(t, devSrc, refSrc)
	t.Logf("excitation against the reference: host %.4g (%.1f dB), device %.4g (%.1f dB)",
		hs.Rel(), -20*math.Log10(hs.Rel()), ds.Rel(), -20*math.Log10(ds.Rel()))
}

// With the excitation noise on, nothing in the spectrum is exactly zero, so
// the phase is defined everywhere and the device and the host should agree
// far better than 19 dB. The noise itself is host-side here: this feeds the
// *same* sine bank to both transforms, so what it isolates is whether the
// undefined phase is really the whole gap.
func TestT7NoiseDefinesThePhase(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	dev, done := newTestDevice(t)
	defer done()
	s, err := NewGPUSource(dev, g, len(f0)+64)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Destroy()

	// The device's own waveform, transformed by both paths.
	devSrc, devHar, err := s.Apply(f0)
	if err != nil {
		t.Fatal(err)
	}
	hostHar := g.Harmonic(devSrc)
	bins := hostHar.Cols / 2
	var n int
	var worst float64
	for i := 0; i < hostHar.Rows; i++ {
		for b := 0; b < bins; b++ {
			mi := i*hostHar.Cols + b
			if float64(hostHar.Data[mi]) < 1e-3 {
				continue
			}
			n++
			d := math.Abs(float64(devHar.Data[mi+bins]) - float64(hostHar.Data[mi+bins]))
			if d > math.Pi {
				d = 2*math.Pi - d
			}
			if d > worst {
				worst = d
			}
		}
	}
	t.Logf("same waveform, both transforms: %d of %d bins have magnitude > 1e-3; worst phase gap there %.3g rad",
		n, hostHar.Rows*bins, worst)
}
