package kokoro

import (
	"math"
	"math/rand"
	"testing"
)

// How wide is the lottery? In the zero-noise configuration the excitation is
// a constant in unvoiced regions, so its windowed spectrum is analytically
// zero outside three bins and the phase there is whatever the rounding says.
// The host's float64 residual, the reference's float32 one and the device's
// float32 one are three different draws of garbage. This replaces the phase
// in those bins with uniform draws and measures what the *waveform* does, so
// that "the device is worse than the host" can be told apart from "the device
// drew a different ticket".
func TestT7PhaseLottery(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	asr := refMat(t, m, "asr", true)
	energy := refCurve(t, m, "n_pred")
	decStyle, _, err := model.Style(m.Voice, len([]rune(m.Phonemes)))
	if err != nil {
		t.Fatal(err)
	}
	want := refCurve(t, m, "audio")
	hostWav, tr, err := model.Vocoder.Apply(asr, f0, energy, decStyle)
	if err != nil {
		t.Fatal(err)
	}
	x := tr.Decode[len(tr.Decode)-1]
	hostHar := tr.Generator.Harmonic
	bins := hostHar.Cols / 2

	h := compare(t, hostWav, want)
	t.Logf("host, its own float64 phase: %.4g (%.1f dB)", h.Rel(), -20*math.Log10(h.Rel()))

	for _, thresh := range []float64{1e-6} {
		for seed := int64(1); seed <= 5; seed++ {
			rng := rand.New(rand.NewSource(seed))
			har := &Mat{Rows: hostHar.Rows, Cols: hostHar.Cols,
				Data: append([]float32{}, hostHar.Data...)}
			var n int
			for i := 0; i < har.Rows; i++ {
				for b := 0; b < bins; b++ {
					mi := i*har.Cols + b
					if float64(har.Data[mi]) >= thresh {
						continue
					}
					n++
					har.Data[mi+bins] = float32((rng.Float64()*2 - 1) * math.Pi)
				}
			}
			got, _, err := g.ApplyWithHarmonic(x, decStyle, har)
			if err != nil {
				t.Fatal(err)
			}
			d := compare(t, got, want)
			t.Logf("  random phase below %g, seed %d (%d bins): %.4g (%.1f dB)",
				thresh, seed, n, d.Rel(), -20*math.Log10(d.Rel()))
		}
	}
}
