// The right null model. In an unvoiced region the excitation is a constant,
// so every frame's spectrum is the *same* numbers and the residual's angle is
// one value per bin repeated across thousands of frames -- not 47075
// independent draws. So the lottery has about eleven tickets in it, and its
// spread is what tells us whether the device's 13.9 dB is a defect or a draw.
func TestT7PerBinLottery(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	asr := refMat(t, m, "asr", true)
	energy := refCurve(t, m, "n_pred")
	decStyle, _, err := model.Style(m.Voice, len([]rune(m.Phonemes)))
	if err != nil {
		t.Fatal(err)
	}
	want := refCurve(t, m, "audio")
	_, tr, err := model.Vocoder.Apply(asr, f0, energy, decStyle)
	if err != nil {
		t.Fatal(err)
	}
	x := tr.Decode[len(tr.Decode)-1]
	hostHar := tr.Generator.Harmonic
	bins := hostHar.Cols / 2

	var lo, hi float64
	for seed := int64(1); seed <= 8; seed++ {
		rng := rand.New(rand.NewSource(seed))
		angle := make([]float32, bins)
		for b := range angle {
			angle[b] = float32((rng.Float64()*2 - 1) * math.Pi)
		}
		h := &Mat{Rows: hostHar.Rows, Cols: hostHar.Cols,
			Data: append([]float32{}, hostHar.Data...)}
		for i := 0; i < h.Rows; i++ {
			for b := 0; b < bins; b++ {
				mi := i*h.Cols + b
				if float64(h.Data[mi]) >= 1e-6 {
					continue
				}
				h.Data[mi+bins] = angle[b]
			}
		}
		got, _, err := g.ApplyWithHarmonic(x, decStyle, h)
		if err != nil {
			t.Fatal(err)
		}
		d := compare(t, got, want)
		db := -20 * math.Log10(d.Rel())
		if seed == 1 || db < lo {
			lo = db
		}
		if seed == 1 || db > hi {
			hi = db
		}
		t.Logf("  one angle per bin, seed %d: %.4g (%.1f dB)", seed, d.Rel(), db)
	}
	t.Logf("spread over 8 draws: %.1f to %.1f dB (host's own float64 phase lands at 18.2, the device at 13.9)", lo, hi)
}
GOEOF
