		if loud[i] != again[i] {
			t.Fatalf("the same seed gave a different waveform at %d: %v against %v", i, loud[i], again[i])
		}
	}
	var same int
	for i := range loud {
		if loud[i] == other[i] {
			same++
		}
	}
	if same > len(loud)/100 {
		t.Errorf("two seeds agree on %d of %d samples", same, len(loud))
	}

