package kokoro

import (
	"math"
	"math/rand"
	"testing"
)

// Is "CPU against the dump = 0.123" a stable number, or one draw? The device
// excitation differs from the host's by 3.5e-6 worst and 1.6e-7 rms. This
// perturbs the *host's* excitation by that much and re-runs the host's own
// transform, so nothing about the device is involved: if 0.123 moves to 0.2
// under a perturbation the size of float32 rounding, then the bound it
// supports is a lottery's and not an arithmetic one.
func TestT7HostStability(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	asr := refMat(t, m, "asr", true)
	energy := refCurve(t, m, "n_pred")
	decStyle, _, err := model.Style(m.Voice, len([]rune(m.Phonemes)))
	if err != nil {
		t.Fatal(err)
	}
	want := refCurve(t, m, "audio")
	_, tr, err := model.Vocoder.Apply(asr, f0, energy, decStyle)
	if err != nil {
		t.Fatal(err)
	}
	x := tr.Decode[len(tr.Decode)-1]
	src, _, _, _ := g.Source.Apply(f0)

	run := func(name string, s []float32) float64 {
		got, _, err := g.ApplyWithHarmonic(x, decStyle, g.Harmonic(s))
		if err != nil {
			t.Fatal(err)
		}
		d := compare(t, got, want)
		t.Logf("  %-26s %.4g (%.1f dB)", name, d.Rel(), -20*math.Log10(d.Rel()))
		return d.Rel()
	}
	run("host excitation as it is", src)

	var lo, hi float64
	for seed := int64(1); seed <= 6; seed++ {
		rng := rand.New(rand.NewSource(seed))
		p := append([]float32{}, src...)
		for i := range p {
			// A perturbation the size of one float32 ulp of the signal, which
			// is smaller than the device's own 3.5e-6 worst case.
			p[i] += float32(rng.NormFloat64() * 1e-7)
		}
		r := run("perturbed by 1e-7 rms", p)
		if seed == 1 || r < lo {
			lo = r
		}
		if seed == 1 || r > hi {
			hi = r
		}
	}
	t.Logf("a 1e-7 rms perturbation of the host excitation moves it over %.4g to %.4g (the device sits at 0.203)", lo, hi)
}
