package kokoro

import (
	"math"
	"testing"
)

// The right null model. In an unvoiced region the excitation is *exactly* a
// constant, and it is the analytic zero of that constant's windowed spectrum
// that leaves the phase undefined. Independent noise breaks the constancy and
// so defines the phase -- which is why perturbing every sample made the
// number better rather than moving it. What the device actually changes is
// **which constant**: its tanh and the host's can differ in the last place.
// So this walks the constant by a few ulps and measures the spread.
func TestT7ConstantLottery(t *testing.T) {
	m := loadManifest(t)
	model := loadModel(t)
	g := model.Vocoder.Generator
	f0 := refCurve(t, m, "f0_pred")
	asr := refMat(t, m, "asr", true)
	energy := refCurve(t, m, "n_pred")
	decStyle, _, err := model.Style(m.Voice, len([]rune(m.Phonemes)))
	if err != nil {
		t.Fatal(err)
	}
	want := refCurve(t, m, "audio")
	_, tr, err := model.Vocoder.Apply(asr, f0, energy, decStyle)
	if err != nil {
		t.Fatal(err)
	}
	x := tr.Decode[len(tr.Decode)-1]
	src, _, uv, _ := g.Source.Apply(f0)

	// The unvoiced constant, and a check that it really is one.
	var c float32
	var n, differ int
	for i := range src {
		if uv[i] != 0 {
			continue
		}
		if n == 0 {
			c = src[i]
		} else if src[i] != c {
			differ++
		}
		n++
	}
	t.Logf("unvoiced constant %v over %d samples, %d of which differ from it", c, n, differ)

	dev, done := newTestDevice(t)
	defer done()
	s, err := NewGPUSource(dev, g, len(f0)+64)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Destroy()
	devSrc, _, err := s.Apply(f0)
	if err != nil {
		t.Fatal(err)
	}
	var dc float32
	for i := range devSrc {
		if uv[i] == 0 {
			dc = devSrc[i]
			break
		}
	}
	t.Logf("the device's unvoiced constant is %v; host %v; they differ by %d ulps",
		dc, c, int(int32(math.Float32bits(dc))-int32(math.Float32bits(c))))

	run := func(name string, s []float32) {
		got, _, err := g.ApplyWithHarmonic(x, decStyle, g.Harmonic(s))
		if err != nil {
			t.Fatal(err)
		}
		d := compare(t, got, want)
		t.Logf("  %-30s %.4g (%.1f dB)", name, d.Rel(), -20*math.Log10(d.Rel()))
	}
	run("host excitation as it is", src)
	for _, k := range []int32{-3, -2, -1, 1, 2, 3} {
		p := append([]float32{}, src...)
		v := math.Float32frombits(uint32(int32(math.Float32bits(c)) + k))
		for i := range p {
			if uv[i] == 0 {
				p[i] = v
			}
		}
		run("unvoiced constant "+itoa(k)+" ulp", p)
	}
}

func itoa(k int32) string {
	if k > 0 {
		return "+" + string(rune('0'+k))
	}
	return "-" + string(rune('0'-k))
}
